//! The filesystem backend.
//!
//! Development only, so a machine needs no cloud credentials to run the
//! stack. It writes under one root and refuses to leave it.

use std::path::{Component, Path, PathBuf};

use super::{Storage, StorageError, StorageResult};

#[derive(Debug, Clone)]
pub struct LocalStorage {
    root: PathBuf,
}

impl LocalStorage {
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// Resolve a key under the root, or refuse.
    ///
    /// Keys are generated by the API, so this should never fire. It is
    /// here because "should never" is how a path traversal gets written:
    /// the day a key does carry `..`, this is the difference between a
    /// rejected request and a file written anywhere on the disk.
    fn path(&self, key: &str) -> StorageResult<PathBuf> {
        let candidate = Path::new(key);

        let safe = candidate
            .components()
            .all(|component| matches!(component, Component::Normal(_)));
        if !safe || key.is_empty() {
            return Err(StorageError::Unavailable("invalid key".into()));
        }

        Ok(self.root.join(candidate))
    }
}

impl Storage for LocalStorage {
    async fn put(&self, key: &str, bytes: &[u8]) -> StorageResult<()> {
        let path = self.path(key)?;

        if let Some(parent) = path.parent() {
            tokio::fs::create_dir_all(parent)
                .await
                .map_err(|error| StorageError::Unavailable(error.to_string()))?;
        }

        tokio::fs::write(&path, bytes)
            .await
            .map_err(|error| StorageError::Unavailable(error.to_string()))
    }

    async fn get(&self, key: &str) -> StorageResult<Vec<u8>> {
        let path = self.path(key)?;

        match tokio::fs::read(&path).await {
            Ok(bytes) => Ok(bytes),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                Err(StorageError::NotFound)
            }
            Err(error) => Err(StorageError::Unavailable(error.to_string())),
        }
    }

    async fn delete(&self, key: &str) -> StorageResult<()> {
        let path = self.path(key)?;

        match tokio::fs::remove_file(&path).await {
            Ok(()) => Ok(()),
            // Deleting what is already gone is the outcome asked for.
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(StorageError::Unavailable(error.to_string())),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn store() -> (LocalStorage, tempdir::TempRoot) {
        let root = tempdir::TempRoot::new();
        (LocalStorage::new(root.path()), root)
    }

    #[tokio::test]
    async fn should_round_trip_bytes() {
        let (storage, _root) = store();

        storage.put("wsp/w1/f1/00000", b"hello").await.unwrap();
        assert_eq!(storage.get("wsp/w1/f1/00000").await.unwrap(), b"hello");

        storage.delete("wsp/w1/f1/00000").await.unwrap();
        assert!(matches!(
            storage.get("wsp/w1/f1/00000").await,
            Err(StorageError::NotFound)
        ));
    }

    #[tokio::test]
    async fn should_treat_deleting_what_is_gone_as_done() {
        let (storage, _root) = store();
        storage.delete("wsp/w1/f1/00000").await.unwrap();
    }

    #[tokio::test]
    async fn should_refuse_a_key_that_climbs_out_of_the_root() {
        let (storage, _root) = store();

        for bad in ["../escape", "wsp/../../escape", "/etc/passwd", ""] {
            assert!(storage.put(bad, b"x").await.is_err(), "accepted {bad:?}");
        }
    }

    /// A scratch directory that cleans up after itself, so the tests need
    /// no temp-directory dependency.
    mod tempdir {
        use std::path::{Path, PathBuf};

        pub struct TempRoot(PathBuf);

        impl TempRoot {
            pub fn new() -> Self {
                let path = std::env::temp_dir().join(format!("oewang-store-{}", cuid()));
                std::fs::create_dir_all(&path).unwrap();
                Self(path)
            }

            pub fn path(&self) -> &Path {
                &self.0
            }
        }

        impl Drop for TempRoot {
            fn drop(&mut self) {
                let _ = std::fs::remove_dir_all(&self.0);
            }
        }

        fn cuid() -> String {
            use std::time::{SystemTime, UNIX_EPOCH};
            let nanos = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos();
            format!("{nanos}-{:?}", std::thread::current().id()).replace(['(', ')', ' '], "")
        }
    }
}
